/** The text in the selected language; a text assembled from known words and numbers is translated word group by word group. */
fun translate(text:String,language:String):String {
    // Every text on the screen passes here at every redraw; the dictionaries are asked once per text (D102).
    val cache=translationCache.getOrPut(language){java.util.concurrent.ConcurrentHashMap()}
    cache[text]?.let {return it}
    val result=translateExact(text,language) ?: fragmentTranslation(text,language){translateExact(it,language)} ?: text
    if(text.length<=200){if(cache.size>6000)cache.clear();cache[text]=result}
    return result
}
private val translationCache=java.util.concurrent.ConcurrentHashMap<String,java.util.concurrent.ConcurrentHashMap<String,String>>()
private fun translateExact(text:String,language:String):String? {
    extraTranslation(text,language)?.let {return it}
    interfaceTranslation(text,language)?.let {return it}
    rigTranslation(text,language)?.let {return it}
    reminderVisualTranslation(text,language)?.let {return it}
    workoutTranslation(text,language)?.let {return it}
    stepTranslation(text,language)?.let {return it}
    transferTranslation(text,language)?.let {return it}
    syncLayoutTranslation(text,language)?.let {return it}
    journalTranslation(text,language)?.let {return it}
    appearanceTranslation(text,language)?.let {return it}
    if(language=="ru")return text
    periodNoteTranslation(text,language)?.let {return it}
    settingsTranslation(text,language)?.let {return it}
    demoTranslation(text,language)?.let {return it}
    identityTranslation(text,language)?.let {return it}
    plannerTranslation(text,language)?.let {return it}
    rows[language]?.get(text)?.let {return it}
    if(text.startsWith("+ "))return "+ "+translate(text.substring(2),language)
    return rows["en"]?.get(text)
}

@Composable fun Text(text:String,modifier:Modifier=Modifier,color:Color=Color.Unspecified,fontSize:TextUnit=TextUnit.Unspecified,style:TextStyle=LocalTextStyle.current) {
    if(captionAsIcon(text,LocalLanguage.current))return
    androidx.compose.material3.Text(translate(text,LocalLanguage.current),modifier=modifier,color=color,fontSize=fontSize,style=style)
}
